from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        if m < n:
            return 0

        suff0 = [0] * n
        suff1 = [0] * n

        def feasible(x: int) -> bool:
            need = (x + points[-1] - 1) // points[-1]
            suff0[-1] = 0
            suff1[-1] = max(need - 1, 0)

            for i in range(n - 2, -1, -1):
                need = (x + points[i] - 1) // points[i]
                w = max(need - 2, 0)
                suff0[i] = max(suff0[i + 1], suff1[i + 1])
                suff1[i] = suff0[i + 1] + w

            if 2 * n - 1 + 2 * max(suff0[0], suff1[0]) <= m:
                return True

            pref0 = pref1 = 0

            for end in range(1, n):
                i = end - 1
                need = (x + points[i] - 1) // points[i]
                w = max(need - 1, 0)

                pref0, pref1 = max(pref0, pref1), pref0 + w

                extra = max(
                    pref0 + max(suff0[end], suff1[end]),
                    pref1 + suff0[end],
                )

                if 2 * n - end - 1 + 2 * extra <= m:
                    return True

            return False

        lo, hi = 1, max(points) * m
        ans = 0

        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1

        return ans
